"""Plantilla GFPI-F-134 V05 incrustada (base64). La genera empaquetar.py: no editar a mano.
Sirve en entornos donde Python no ve assets/ (p. ej. ChatGPT): los generadores la usan si falta el .xlsx.
"""
import base64
import tempfile
from pathlib import Path

XLSX_B64 = ""


def ruta_plantilla(plantilla=None):
    """Ruta de la plantilla: la indicada, la de assets/ o una copia reconstruida desde XLSX_B64."""
    if plantilla:
        return Path(plantilla)
    en_assets = Path(__file__).resolve().parents[1] / "assets" / "GFPI-F-134 Formato Planeacion Pedagogica.xlsx"
    if en_assets.exists():
        return en_assets
    copia = Path(tempfile.gettempdir()) / "GFPI-F-134_Formato_Planeacion_Pedagogica.xlsx"
    datos = base64.b64decode(XLSX_B64)
    if not copia.exists() or copia.read_bytes() != datos:
        copia.write_bytes(datos)
    return copia
